import logging
from . import bus, adxl345, bulk_sensor
REG_QMI8658A_WHO_AM_I_ADDR = 0
REG_QMI8658A_CTRL1_ADDR = 2
REG_QMI8658A_CTRL2_ADDR = 3
REG_QMI8658A_CTRL3_ADDR = 4
REG_QMI8658A_CTRL4_ADDR = 5
REG_QMI8658A_CTRL5_ADDR = 6
REG_QMI8658A_CTRL6_ADDR = 7
REG_QMI8658A_CTRL7_ADDR = 8
REG_QMI8658A_CTRL8_ADDR = 9
REG_QMI8658A_FIFO_WTM_TH_ADDR = 19
REG_QMI8658A_FIFO_CTRL_ADDR = 20
REG_QMI8658A_FIFO_SMPL_CNT_ADDR = 21
REG_QMI8658A_FIFO_STATUS_ADDR = 22
REG_QMI8658A_FIFO_DATA_ADDR = 23
REG_MOD_READ = 128
QMI8658A_DEV_ID = 5
FREEFALL_ACCEL = 9.80665
SCALE = FREEFALL_ACCEL / 2048
BATCH_UPDATES = 0.1

class QMI8658A:

    def __init__(self, config):
        self.printer = config.get_printer()
        adxl345.AccelCommandHelper(config, self)
        self.axes_map = adxl345.read_axes_map(config, SCALE, SCALE, SCALE)
        self.data_rate = 1600
        self.spi = bus.MCU_SPI_from_config(config, 3, default_speed=5000000)
        self.mcu = mcu = self.spi.get_mcu()
        self.oid = oid = mcu.create_oid()
        self.query_qmi8658a_cmd = None
        mcu.add_config_cmd("config_qmi8658a oid=%d spi_oid=%d" % (
         oid, self.spi.get_oid()))
        mcu.add_config_cmd(("query_qmi8658a oid=%d rest_ticks=0" % (
         oid,)),
          on_restart=True)
        mcu.register_config_callback(self._build_config)
        chip_smooth = self.data_rate * BATCH_UPDATES * 2
        self.ffreader = bulk_sensor.FixedFreqReader(mcu, chip_smooth, "<hhh")
        self.last_error_count = 0
        self.batch_bulk = bulk_sensor.BatchBulkHelper(self.printer, self._process_batch, self._start_measurements, self._finish_measurements, BATCH_UPDATES)
        self.name = config.get_name().split()[-1]
        hdr = ('time', 'x_acceleration', 'y_acceleration', 'z_acceleration')
        self.batch_bulk.add_mux_endpoint("qmi8658a/dump_qmi8658a", "sensor", self.name, {"header": hdr})

    def _build_config(self):
        cmdqueue = self.spi.get_command_queue()
        self.query_qmi8658a_cmd = self.mcu.lookup_command("query_qmi8658a oid=%c rest_ticks=%u",
          cq=cmdqueue)
        self.ffreader.setup_query_command("query_qmi8658a_status oid=%c", oid=(self.oid),
          cq=cmdqueue)

    def read_reg(self, reg):
        params = self.spi.spi_transfer([reg | REG_MOD_READ, 0])
        response = bytearray(params["response"])
        return response[1]

    def set_reg(self, reg, val, minclock=0):
        self.spi.spi_send([reg, val & 255], minclock=minclock)
        stored_val = self.read_reg(reg)
        if stored_val != val:
            raise self.printer.command_error("Failed to set QMI8658A register [0x%x] to 0x%x: got 0x%x. This is generally indicative of connection problems (e.g. faulty wiring) or a faulty qmi8658a chip." % (
             reg, val, stored_val))

    def start_internal_client(self):
        aqh = adxl345.AccelQueryHelper(self.printer)
        self.batch_bulk.add_client(aqh.handle_batch)
        return aqh

    def _convert_samples(self, samples):
        ((x_pos, x_scale), (y_pos, y_scale), (z_pos, z_scale)) = self.axes_map
        count = 0
        for (ptime, rx, ry, rz) in samples:
            raw_xyz = (
             rx, ry, rz)
            x = round(raw_xyz[x_pos] * x_scale, 6)
            y = round(raw_xyz[y_pos] * y_scale, 6)
            z = round(raw_xyz[z_pos] * z_scale, 6)
            samples[count] = (round(ptime, 6), x, y, z)
            count += 1

    def _start_measurements(self):
        try:
            dev_id = self.read_reg(REG_QMI8658A_WHO_AM_I_ADDR)
            logging.info("qmi8658a_dev_id: %x", dev_id)
            if dev_id != QMI8658A_DEV_ID:
                raise self.printer.command_error("Invalid qmi8658a id (got %x vs %x).\nThis is generally indicative of connection problems\n(e.g. faulty wiring) or a faulty qmi8658a chip." % (
                 dev_id, QMI8658A_DEV_ID))
            self.set_reg(REG_QMI8658A_CTRL2_ADDR, 176)
            self.set_reg(REG_QMI8658A_FIFO_CTRL_ADDR, 2)
            rest_ticks = self.mcu.seconds_to_clock(4.0 / self.data_rate)
            self.query_qmi8658a_cmd.send([self.oid, rest_ticks])
            self.set_reg(REG_QMI8658A_FIFO_CTRL_ADDR, 2)
            logging.info("QMI8658A starting '%s' measurements", self.name)
        except self.printer.command_error as e:
            try:
                raise self.printer.command_error("Failed to set QMI8658A register start measurements")
            finally:
                e = None
                del e

        else:
            self.ffreader.note_start()
            self.last_error_count = 0

    def _finish_measurements(self):
        error_record = None
        try:
            self.set_reg(REG_QMI8658A_FIFO_CTRL_ADDR, 0)
        except self.printer.command_error as e:
            try:
                error_record = e
            finally:
                e = None
                del e

        else:
            self.query_qmi8658a_cmd.send_wait_ack([self.oid, 0])
            self.ffreader.note_end()
            logging.info("QMI8658A finished '%s' measurements", self.name)
            try:
                self.set_reg(REG_QMI8658A_FIFO_CTRL_ADDR, 0)
            except self.printer.command_error as e:
                try:
                    error_record = e
                finally:
                    e = None
                    del e

            else:
                if error_record is not None:
                    raise error_record

    def _process_batch(self, eventtime):
        samples = self.ffreader.pull_samples()
        self._convert_samples(samples)
        if not samples:
            return {}
        return {'data':samples,  'errors':self.last_error_count,  'overflows':(self.ffreader.get_last_overflows)()}


def load_config(config):
    return QMI8658A(config)


def load_config_prefix(config):
    return QMI8658A(config)

